#' Dynamic EGA
#'
#' Estimates the dimensional structure of intensive longitudinal data (many 
#' measurements per person) with dynamic Exploratory Graph Analysis: 
#' derivatives of each person's time series, and their structure for the whole 
#' sample, for each group and for each person, with plain-language 
#' interpretation.
#' 
#' @param data .
#' @param vars .
#' @param id .
#' @param time .
#' @param group .
#' @param reportLang .
#' @param nEmbed .
#' @param tau .
#' @param delta .
#' @param derivative .
#' @param corr .
#' @param model .
#' @param algorithm .
#' @param uniMethod .
#' @param seed .
#' @param levelGroup .
#' @param levelIndividual .
#' @param showIndTable .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showNetworkPlot .
#' @param showIndPlot .
#' @param plotPalette .
#' @param layout .
#' @param plotTitle .
#' @param nodeSize .
#' @param nodeShape .
#' @param nodeAlpha .
#' @param labelSize .
#' @param labelColor .
#' @param edgeSize .
#' @param edgePosColor .
#' @param edgeNegColor .
#' @param edgeNegLty .
#' @param edgeMin .
#' @param showEdgeLabels .
#' @param edgeLabelSize .
#' @param edgeLabelDigits .
#' @param showLegend .
#' @param legendPosition .
#' @param legendTitle .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$status} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$membership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groupTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$networkPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$indStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$indFreq} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$indAgree} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$indTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$indPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$indInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
dynega <- function(
    data,
    vars,
    id = NULL,
    time = NULL,
    group = NULL,
    reportLang = "en",
    nEmbed = 5,
    tau = 1,
    delta = 1,
    derivative = "1",
    corr = "auto",
    model = "glasso",
    algorithm = "walktrap",
    uniMethod = "louvain",
    seed = 2026,
    levelGroup = TRUE,
    levelIndividual = FALSE,
    showIndTable = FALSE,
    showKeySummary = TRUE,
    showChoicesGuide = TRUE,
    showNetworkPlot = TRUE,
    showIndPlot = TRUE,
    plotPalette = "default",
    layout = "qgraph",
    plotTitle = "",
    nodeSize = 12,
    nodeShape = "circle",
    nodeAlpha = 0.5,
    labelSize = 5,
    labelColor = "black",
    edgeSize = 8,
    edgePosColor = "darkgreen",
    edgeNegColor = "red",
    edgeNegLty = "solid",
    edgeMin = 0,
    showEdgeLabels = FALSE,
    edgeLabelSize = 3,
    edgeLabelDigits = 2,
    showLegend = TRUE,
    legendPosition = "right",
    legendTitle = "") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("dynega requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(id)) id <- jmvcore::resolveQuo(jmvcore::enquo(id))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(id), id, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- dynegaOptions$new(
        vars = vars,
        id = id,
        time = time,
        group = group,
        reportLang = reportLang,
        nEmbed = nEmbed,
        tau = tau,
        delta = delta,
        derivative = derivative,
        corr = corr,
        model = model,
        algorithm = algorithm,
        uniMethod = uniMethod,
        seed = seed,
        levelGroup = levelGroup,
        levelIndividual = levelIndividual,
        showIndTable = showIndTable,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showNetworkPlot = showNetworkPlot,
        showIndPlot = showIndPlot,
        plotPalette = plotPalette,
        layout = layout,
        plotTitle = plotTitle,
        nodeSize = nodeSize,
        nodeShape = nodeShape,
        nodeAlpha = nodeAlpha,
        labelSize = labelSize,
        labelColor = labelColor,
        edgeSize = edgeSize,
        edgePosColor = edgePosColor,
        edgeNegColor = edgeNegColor,
        edgeNegLty = edgeNegLty,
        edgeMin = edgeMin,
        showEdgeLabels = showEdgeLabels,
        edgeLabelSize = edgeLabelSize,
        edgeLabelDigits = edgeLabelDigits,
        showLegend = showLegend,
        legendPosition = legendPosition,
        legendTitle = legendTitle)

    analysis <- dynegaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

